#pragma once
#include <stdint.h>

struct SokobanGame {
  static constexpr int COLS = 8, ROWS = 6, LEVELS = 10, HISTORY = 128;
  // Original compact puzzles, generated by legal reverse pulls and solved offline.
  static const char *layout(int level) {
    static const char *const maps[LEVELS] = {
    "########""#      #""# @$ . #""#      #""#      #""########",
    "########""#      #""#   . .#""#  $@$ #""#      #""########",
    "########""#   .  #""#  # $ #""# $  .@#""#      #""########",
    "########""#.     #""# #  $@#""#  * # #""#      #""########",
    "########""#  @ . #""# $##$ #""#    . #""#      #""########",
    "########""#      #""#   .@ #""# *$ $ #""#.     #""########",
    "########""#   @. #""# $#   #""# $ $. #""#.     #""########",
    "########""# .@$  #""# # *. #""# $  # #""#      #""########",
    "########""#.     #""#@*##$ #""#      #""# $ .  #""########",
    "########""#.   $@#""#  . $$#""#      #""#     .#""########",
    };
    return maps[level % LEVELS];
  }
  uint64_t walls = 0, goals = 0, boxes = 0;
  uint8_t player = 0, level = 0;
  uint16_t moves = 0, pushes = 0;
  struct State { uint64_t boxes; uint16_t moves, pushes; uint8_t player; };
  State history[HISTORY];
  uint8_t historyHead = 0, historyCount = 0;
  static uint64_t cellMask(int cell) { return uint64_t(1) << cell; }
  bool solved() const { return boxes == goals; }
  void reset(uint8_t which) {
    level = which < LEVELS ? which : 0;
    walls = goals = boxes = 0; moves = pushes = 0; historyHead = historyCount = 0;
    const char *map = layout(level);
    for (int i = 0; i < COLS * ROWS; ++i) {
      char c = map[i];
      if (c == '#') walls |= cellMask(i);
      if (c == '.' || c == '*' || c == '+') goals |= cellMask(i);
      if (c == '$' || c == '*') boxes |= cellMask(i);
      if (c == '@' || c == '+') player = i;
    }
  }
  int neighbor(int cell, int dx, int dy) const {
    int x = cell % COLS + dx, y = cell / COLS + dy;
    return x < 0 || x >= COLS || y < 0 || y >= ROWS ? -1 : y * COLS + x;
  }
  bool move(int dx, int dy) {
    if ((dx != 0 && dy != 0) || dx < -1 || dx > 1 || dy < -1 || dy > 1 || (!dx && !dy)) return false;
    int to = neighbor(player, dx, dy);
    if (to < 0 || (walls & cellMask(to))) return false;
    bool push = boxes & cellMask(to);
    int beyond = push ? neighbor(to, dx, dy) : -1;
    if (push && (beyond < 0 || ((walls | boxes) & cellMask(beyond)))) return false;
    history[historyHead] = {boxes, moves, pushes, player};
    historyHead = (historyHead + 1) % HISTORY;
    if (historyCount < HISTORY) ++historyCount;
    if (push) { boxes ^= cellMask(to) | cellMask(beyond); ++pushes; }
    player = to; ++moves;
    return true;
  }
  bool undo() {
    if (!historyCount) return false;
    historyHead = (historyHead + HISTORY - 1) % HISTORY; --historyCount;
    const State &state = history[historyHead];
    boxes = state.boxes; player = state.player; moves = state.moves; pushes = state.pushes;
    return true;
  }
};
